// Only IDs come in. Everything else is fetched from LeadPilot.
const body = $input.first().json.body ?? {};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const valid = uuid.test(String(body.request_id ?? '')) && uuid.test(String(body.lead_id ?? ''));
return [{ json: { valid, request_id: body.request_id ?? null, lead_id: body.lead_id ?? null, execution_id: $execution.id } }];

// Build the prompt. Lead data is serialized as JSON and fenced inside
// <lead_data> tags; angle brackets in values are neutralized so prospect text
// can't close the fence or open new instructions.
const ctx = $input.first().json;
const clean = (v) => typeof v === 'string' ? v.replace(/[<>]/g, ' ').slice(0, 1000) : v;
const lead = Object.fromEntries(Object.entries(ctx.lead ?? {}).map(([k, v]) => [k, Array.isArray(v) ? v.map(clean) : clean(v)]));
const data = { lead, brokerage: { name: 'Northstar Realty', agent_first_name: clean(ctx.brokerage?.agent_first_name ?? 'The Northstar team') } };
const prompt = 'Analyze this lead and answer with the JSON object only.\n<lead_data>\n' + JSON.stringify(data, null, 2) + '\n</lead_data>';
return [{ json: { request_id: ctx.request_id, prompt } }];

// Pull the model's answer out of the Gemini node output, whatever its shape.
const item = $input.first().json;
let model = 'gemini';
try { const p = $('Analyze lead with Gemini').params; model = String(p.modelId?.value ?? p.modelId ?? model).replace(/^models\//, ''); } catch (e) {}

function find(node, depth = 0) {
  if (node == null || depth > 8) return null;
  if (typeof node === 'object' && !Array.isArray(node) && 'interest_level' in node) return node;
  if (typeof node === 'string') return node.includes('{') ? node : null;
  if (Array.isArray(node)) { for (const v of node) { const r = find(v, depth + 1); if (r) return r; } return null; }
  for (const key of ['content', 'parts', 'candidates', 'message', 'text', 'output', 'response']) {
    if (key in node) { const r = find(node[key], depth + 1); if (r) return r; }
  }
  for (const v of Object.values(node)) { const r = find(v, depth + 1); if (r) return r; }
  return null;
}

const output = find(item);
return [{ json: {
  request_id: $('Build prompt').first().json.request_id,
  execution_id: $execution.id,
  model,
  ...(output ? { output } : { error: 'Gemini returned no usable text' }),
} }];

// Any failure (LeadPilot context unavailable, Gemini key missing, quota
// exceeded…) is reported back so LeadPilot shows it instead of hanging.
const item = $input.first().json;
const err = item.error;
const message = typeof err === 'string' ? err : (err?.message ?? err?.description ?? JSON.stringify(err ?? item).slice(0, 500));
let requestId = null;
try { requestId = $('Validate request').first().json.request_id; } catch (e) {}
return [{ json: { request_id: requestId, execution_id: $execution.id, error: String(message).slice(0, 1500) } }];
